def top_k(lst, k):

    if lst == []:
        return lst

    lower = []
    higher = []
    plist = []

    pivot = lst[0]
    for e in lst:
        if e < pivot:
            lower.append(e)
        if e == pivot:
            plist.append(e)
        if e > pivot:
            higher.append(e)
    sort_list = top_k(higher, len(higher)) + plist + top_k(lower, len(lower))

    return sort_list[:k]

