def top_k(lst, k):

    if lst == []:
        return lst

    def quick_sort(lst):
        if len(lst) == 0:
            return []
        lower = []
        higher = []
        plist = []

        pivot = lst[0]
        for e in lst:
            if e < pivot:
                lower.append(e)
            if e == pivot:
                plist.append(e)
            if e > pivot:
                higher.append(e)
        return quick_sort(lower) + plist + quick_sort(higher)

    sort_list = quick_sort(lst)[::-1]

    if k == len(lst):
        return sort_list[:k]
    elif k > len(lst):
        return sort_list
    else:
        return sort_list[:k]

