def sort_list(lst):
    a = lst[:]
    n = len(a)
    for i in range(n):
        max_i = i
        for j in range(i + 1, n):
            if a[j] > a[max_i]:
                max_i = j
        a[i], a[max_i] = a[max_i], a[i]
    return a

